{
  "query": "query GetProductDetails($uid: String, $posItemCode: String, $skip: Int!, $limit: Int!) { getProducts(pagination: { skip: $skip, limit: $limit }, filter: { uid: $uid, posItemCode: $posItemCode }) { message statusCode result { count products { uid enName images { url } productAttributes { enLabel values { enName } } detailedDescriptions { enLabel values { enName } } deliveries { enLabel values { enName } } serviceAndDeliveries { enLabel values { enName } } priceAndStocks { enLabel values { enName } } variants { mrpPrice ebsItemCode posItemCode quantity discount { amount value type } } } } } }",
  "variables": {
    "uid": "{{uid}}",
    "posItemCode": null,
    "skip": {{skip}},
    "limit": {{limit}}
  }
}
